import React, { useState, useEffect, useMemo, useRef } from "react";
import Cropper from "react-easy-crop";

// --- 注入優化過的日式質感樣式（解決手機左右滑動問題） ---
const styleTag = `
  :root {
    --bg-color-start: #f8f6f2; 
    --bg-color-end: #e8e2d2;   
    --card-bg: #ffffff;      
    --accent-color: #7c6d60;  
    --text-main: #4a4a4a;    
    --text-muted: #a09a8e;   
    --border-color: #e0ddd5;  
    --btn-secondary: #e0ddd5;
  }

  * {
    box-sizing: border-box; /* 防止 Padding 撐開寬度的關鍵 */
  }

  body {
    background: linear-gradient(135deg, var(--bg-color-start), var(--bg-color-end)) !important;
    margin: 0; 
    padding: 0;
    min-height: 100vh;
    font-family: "Noto Sans TC", "Microsoft JhengHei", sans-serif;
    overflow-x: hidden; /* 防止身體橫向溢出 */
  }

  .container {
    max-width: 900px; 
    width: 95%; /* 在手機上自動留邊 */
    margin: 20px auto; 
    padding: 20px;
    background: rgba(255, 255, 255, 0.4); 
    border-radius: 20px;
    backdrop-filter: blur(10px); 
    box-shadow: 0 10px 30px rgba(0,0,0,0.05);
    overflow: hidden; 
  }

  .header h1 { text-align: center; color: var(--accent-color); letter-spacing: 5px; font-weight: 300; margin-bottom: 5px; font-size: 1.8rem; }

  .input-section {
    background: white; padding: 20px; border-radius: 15px;
    box-shadow: 0 8px 20px rgba(140, 123, 108, 0.1); margin-bottom: 30px; border: 1px solid var(--border-color);
  }

  .yarn-card {
    background: white; border-radius: 15px; overflow: hidden;
    box-shadow: 0 10px 20px rgba(140, 123, 108, 0.1); position: relative;
    transition: transform 0.3s ease; border: 1px solid var(--border-color);
    width: 100%;
  }

  .image-wrapper { height: 200px; background: #f0ede5; overflow: hidden; border-bottom: 1px solid var(--border-color); }
  .image-wrapper img { width: 100%; height: 100%; object-fit: cover; }
  .card-content { padding: 15px; }

  .info-tag {
    background: #f0ede5; color: var(--accent-color); padding: 3px 10px;
    border-radius: 5px; font-size: 12px; margin-right: 5px; display: inline-block; margin-top: 5px;
  }

  .submit-btn {
    background: var(--accent-color); color: white; border: none; padding: 15px;
    border-radius: 10px; width: 100%; cursor: pointer; font-size: 16px; margin-top: 15px;
  }

  .toolbar, .backup-bar {
    display: flex; justify-content: space-between; gap: 10px; margin-bottom: 20px;
    background: white; padding: 12px 15px; border-radius: 12px; border: 1px solid var(--border-color);
    flex-wrap: wrap; /* 讓內容在手機上自動換行 */
  }

  .backup-btn {
    background: var(--btn-secondary); color: var(--text-main); border: none;
    padding: 8px 12px; border-radius: 8px; cursor: pointer; font-size: 13px;
  }

  .edit-input {
    width: 100%; border: 1px solid var(--accent-color); border-radius: 6px; padding: 6px; 
    font-size: 14px; margin-bottom: 8px; outline: none;
  }

  input, select { 
    padding: 10px; border: 1px solid var(--border-color); border-radius: 8px; outline: none; 
    width: 100%; /* 讓輸入框預設填滿 */
  }

  /* 手機版排版優化 */
  @media (max-width: 600px) {
    .container { padding: 15px; margin: 10px auto; }
    .header h1 { font-size: 1.5rem; letter-spacing: 2px; }
    
    /* 讓表單內的格狀排列在手機上變成垂直 */
    .form-grid { grid-template-columns: 1fr !important; }
    
    .toolbar, .backup-bar { flex-direction: column; align-items: stretch; }
    .backup-btn { width: 100%; margin-bottom: 5px; }
  }

  .crop-modal {
    position: fixed; top: 0; left: 0; right: 0; bottom: 0;
    background: rgba(0,0,0,0.9); z-index: 9999;
    display: flex; flex-direction: column; align-items: center; justify-content: center;
  }
`;

// 執行樣式注入
if (typeof document !== "undefined") {
  const style = document.createElement("style");
  style.innerHTML = styleTag;
  document.head.appendChild(style);
}

export default function App() {
  const [yarns, setYarns] = useState(() => {
    const saved = localStorage.getItem("yarn_stash_vFinal");
    return saved ? JSON.parse(saved) : [];
  });

  const [formData, setFormData] = useState({
    name: "",
    shop: "",
    weight: "",
    count: "",
    thickness: "2.0mm",
    image: null as string | null,
  });

  const [editingId, setEditingId] = useState<number | null>(null);
  const [editData, setEditData] = useState<any>(null);

  const [filterThickness, setFilterThickness] = useState("全部");
  const [sortOrder, setSortOrder] = useState("newest");
  const [imageToCrop, setImageToCrop] = useState<string | null>(null);
  const [crop, setCrop] = useState({ x: 0, y: 0 });
  const [zoom, setZoom] = useState(1);
  const [croppedAreaPixels, setCroppedAreaPixels] = useState<any>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    localStorage.setItem("yarn_stash_vFinal", JSON.stringify(yarns));
  }, [yarns]);

  const startEdit = (yarn: any) => {
    setEditingId(yarn.id);
    setEditData({ ...yarn });
  };

  const saveEdit = () => {
    setYarns(yarns.map((y: any) => (y.id === editingId ? editData : y)));
    setEditingId(null);
  };

  const exportData = () => {
    const dataStr = JSON.stringify(yarns);
    const dataUri =
      "data:application/json;charset=utf-8," + encodeURIComponent(dataStr);
    const link = document.createElement("a");
    link.setAttribute("href", dataUri);
    link.setAttribute(
      "download",
      `yarn_backup_${new Date().toLocaleDateString()}.json`
    );
    link.click();
  };

  const importData = (e: any) => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event: any) => {
      const imported = JSON.parse(event.target.result);
      if (Array.isArray(imported) && window.confirm("確定要匯入嗎？"))
        setYarns(imported);
    };
    reader.readAsText(file);
  };

  const thicknessOptions = [
    "2.0mm",
    "2.5mm",
    "3.0mm",
    "3.5mm",
    "4.0mm",
    "4.5mm",
    "5.0mm",
    "5.5mm",
    "6.0mm",
    "手混線",
  ];

  const processedYarns = useMemo(() => {
    let result = [...yarns];
    if (filterThickness !== "全部")
      result = result.filter((y) => y.thickness === filterThickness);
    sortOrder === "newest"
      ? result.sort((a, b) => b.id - a.id)
      : result.sort((a, b) => a.id - b.id);
    return result;
  }, [yarns, filterThickness, sortOrder]);

  const handleCropSave = async () => {
    const croppedImage = await getCroppedImg(imageToCrop, croppedAreaPixels);
    setFormData({ ...formData, image: croppedImage });
    setImageToCrop(null);
  };

  return (
    <div className="container">
      <header className="header">
        <h1>安安の毛線棚</h1>
        <p
          style={{
            textAlign: "center",
            color: "#a09a8e",
            marginBottom: "20px",
            fontSize: "14px",
          }}
        >
          紀錄每一團編織的記憶
        </p>
      </header>

      <div className="backup-bar">
        <span style={{ fontSize: "13px", color: "#7c6d60" }}>💾 資料備份</span>
        <div style={{ display: "flex", gap: "5px" }}>
          <button className="backup-btn" onClick={exportData}>
            匯出
          </button>
          <button
            className="backup-btn"
            onClick={() => fileInputRef.current?.click()}
          >
            匯入
          </button>
          <input
            type="file"
            ref={fileInputRef}
            hidden
            accept=".json"
            onChange={importData}
          />
        </div>
      </div>

      {imageToCrop && (
        <div className="crop-modal">
          <div
            style={{
              position: "relative",
              width: "90%",
              height: "300px",
              maxWidth: "400px",
            }}
          >
            <Cropper
              image={imageToCrop}
              crop={crop}
              zoom={zoom}
              aspect={4 / 3}
              onCropChange={setCrop}
              onCropComplete={(u, p) => setCroppedAreaPixels(p)}
              onZoomChange={setZoom}
            />
          </div>
          <div
            style={{
              background: "white",
              padding: "20px",
              width: "90%",
              maxWidth: "400px",
              borderRadius: "0 0 15px 15px",
            }}
          >
            <input
              type="range"
              min="1"
              max="3"
              step="0.1"
              value={zoom}
              onChange={(e: any) => setZoom(e.target.value)}
              style={{ marginBottom: "15px" }}
            />
            <div style={{ display: "flex", justifyContent: "space-between" }}>
              <button
                onClick={() => setImageToCrop(null)}
                style={{
                  padding: "8px 20px",
                  borderRadius: "8px",
                  border: "1px solid #ddd",
                }}
              >
                取消
              </button>
              <button
                onClick={handleCropSave}
                style={{
                  background: "#7c6d60",
                  color: "white",
                  border: "none",
                  padding: "8px 20px",
                  borderRadius: "8px",
                }}
              >
                完成
              </button>
            </div>
          </div>
        </div>
      )}

      <section className="input-section">
        <form
          onSubmit={(e: any) => {
            e.preventDefault();
            setYarns([{ ...formData, id: Date.now() }, ...yarns]);
            setFormData({
              name: "",
              shop: "",
              weight: "",
              count: "",
              thickness: "2.0mm",
              image: null,
            });
          }}
        >
          <div
            className="form-grid"
            style={{
              display: "grid",
              gridTemplateColumns: "1fr 1fr",
              gap: "10px",
              marginBottom: "10px",
            }}
          >
            <input
              type="text"
              placeholder="毛線名稱"
              value={formData.name}
              onChange={(e: any) =>
                setFormData({ ...formData, name: e.target.value })
              }
              required
            />
            <input
              type="text"
              placeholder="購買店家"
              value={formData.shop}
              onChange={(e: any) =>
                setFormData({ ...formData, shop: e.target.value })
              }
            />
          </div>
          <div
            className="form-grid"
            style={{
              display: "grid",
              gridTemplateColumns: "1fr 1fr 1fr",
              gap: "10px",
            }}
          >
            <select
              value={formData.thickness}
              onChange={(e: any) =>
                setFormData({ ...formData, thickness: e.target.value })
              }
            >
              {thicknessOptions.map((opt) => (
                <option key={opt} value={opt}>
                  {opt}
                </option>
              ))}
            </select>
            <input
              type="number"
              placeholder="重量(g)"
              value={formData.weight}
              onChange={(e: any) =>
                setFormData({ ...formData, weight: e.target.value })
              }
            />
            <input
              type="number"
              placeholder="顆數"
              value={formData.count}
              onChange={(e: any) =>
                setFormData({ ...formData, count: e.target.value })
              }
            />
          </div>
          <div
            style={{
              marginTop: "15px",
              padding: "15px",
              border: "2px dashed #e0ddd5",
              textAlign: "center",
              borderRadius: "12px",
            }}
          >
            <label
              style={{ cursor: "pointer", color: "#7c6d60", fontSize: "14px" }}
            >
              {formData.image ? "✅ 已選好照片" : "📷 上傳並調整照片"}
              <input
                type="file"
                hidden
                onChange={(e: any) => {
                  const file = e.target.files[0];
                  if (file) {
                    const reader = new FileReader();
                    reader.onload = () =>
                      setImageToCrop(reader.result as string);
                    reader.readAsDataURL(file);
                  }
                }}
                accept="image/*"
              />
            </label>
          </div>
          <button type="submit" className="submit-btn">
            記錄新毛線
          </button>
        </form>
      </section>

      <div className="toolbar">
        <div>
          篩選：
          <select
            style={{ width: "auto", marginLeft: "5px" }}
            value={filterThickness}
            onChange={(e: any) => setFilterThickness(e.target.value)}
          >
            <option value="全部">全部顯示</option>
            {thicknessOptions.map((opt) => (
              <option key={opt} value={opt}>
                {opt}
              </option>
            ))}
          </select>
        </div>
        <div>
          排序：
          <select
            style={{ width: "auto", marginLeft: "5px" }}
            value={sortOrder}
            onChange={(e: any) => setSortOrder(e.target.value)}
          >
            <option value="newest">最新優先</option>
            <option value="oldest">最舊優先</option>
          </select>
        </div>
      </div>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fill, minmax(250px, 1fr))",
          gap: "25px",
        }}
      >
        {processedYarns.map((yarn) => (
          <div key={yarn.id} className="yarn-card">
            <div className="image-wrapper">
              {yarn.image ? (
                <img src={yarn.image} alt="" />
              ) : (
                <div
                  style={{
                    textAlign: "center",
                    lineHeight: "200px",
                    color: "#a09a8e",
                  }}
                >
                  待撮影
                </div>
              )}
            </div>
            <div className="card-content">
              {editingId === yarn.id ? (
                <div>
                  <input
                    className="edit-input"
                    value={editData.name}
                    onChange={(e) =>
                      setEditData({ ...editData, name: e.target.value })
                    }
                  />
                  <div
                    style={{ display: "flex", gap: "5px", marginBottom: "8px" }}
                  >
                    <input
                      className="edit-input"
                      type="number"
                      value={editData.weight}
                      onChange={(e) =>
                        setEditData({ ...editData, weight: e.target.value })
                      }
                      placeholder="g"
                    />
                    <input
                      className="edit-input"
                      type="number"
                      value={editData.count}
                      onChange={(e) =>
                        setEditData({ ...editData, count: e.target.value })
                      }
                      placeholder="顆"
                    />
                  </div>
                  <button
                    onClick={saveEdit}
                    style={{
                      width: "100%",
                      background: "#7c6d60",
                      color: "white",
                      border: "none",
                      borderRadius: "6px",
                      padding: "8px",
                    }}
                  >
                    儲存修改
                  </button>
                </div>
              ) : (
                <>
                  <div
                    style={{
                      fontSize: "18px",
                      fontWeight: "bold",
                      marginBottom: "8px",
                      color: "#333",
                      display: "flex",
                      justifyContent: "space-between",
                    }}
                  >
                    {yarn.name}
                    <button
                      onClick={() => startEdit(yarn)}
                      style={{
                        background: "none",
                        border: "none",
                        color: "#a09a8e",
                        cursor: "pointer",
                      }}
                    >
                      ✎
                    </button>
                  </div>
                  <div style={{ marginBottom: "10px" }}>
                    <span className="info-tag">{yarn.thickness}</span>
                    {yarn.shop && <span className="info-tag">{yarn.shop}</span>}
                  </div>
                  <div
                    style={{
                      fontSize: "13px",
                      borderTop: "1px dashed #e0ddd5",
                      paddingTop: "10px",
                      display: "flex",
                      justifyContent: "space-between",
                    }}
                  >
                    <span>重量: {yarn.weight || 0} g</span>
                    <span>數量: {yarn.count || 0} 顆</span>
                  </div>
                </>
              )}
            </div>
            <button
              onClick={() => {
                if (window.confirm("確定刪除？"))
                  setYarns(yarns.filter((y: any) => y.id !== yarn.id));
              }}
              style={{
                position: "absolute",
                top: "8px",
                right: "8px",
                background: "rgba(255,255,255,0.8)",
                border: "none",
                borderRadius: "50%",
                width: "24px",
                height: "24px",
                cursor: "pointer",
              }}
            >
              ×
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

async function getCroppedImg(imageSrc: any, pixelCrop: any) {
  const image = new Image();
  image.src = imageSrc;
  await new Promise((r) => (image.onload = r));
  const canvas = document.createElement("canvas");
  const scale = Math.min(1, 800 / pixelCrop.width);
  canvas.width = pixelCrop.width * scale;
  canvas.height = pixelCrop.height * scale;
  const ctx = canvas.getContext("2d");
  ctx!.drawImage(
    image,
    pixelCrop.x,
    pixelCrop.y,
    pixelCrop.width,
    pixelCrop.height,
    0,
    0,
    canvas.width,
    canvas.height
  );
  return canvas.toDataURL("image/jpeg", 0.6);
}
